// Fetches example images for the prototypes from the Unsplash API, once, and
// writes their public URLs + photographer credits to prototypes/data/.
// The access key stays in the git-ignored .env.prototype; the output holds no key.
//
//   node --env-file=.env.prototype prototypes/tools/fetch-unsplash.js
//
// Unsplash rules followed (help.unsplash.com, checked 2026-10-02): images are
// hotlinked from the returned photo.urls (ixid kept), and every photo shown is
// credited to its photographer with a utm-tagged link back to Unsplash.
// Which surface each set stands in for: docs/features/imagery-surfaces.md.
const fs = require("fs");
const path = require("path");

const KEY = process.env.UNSPLASH_ACCESS_KEY;
if (!KEY) throw new Error("UNSPLASH_ACCESS_KEY missing — run with --env-file=.env.prototype");
const UTM = "utm_source=king_domain_prototype&utm_medium=referral";

// Each set is a stand-in for one imagery surface (see the doc above).
const SETS = {
  // Surface 2: profile photos. Nigerian students, so search for them specifically.
  people: { query: "nigerian student portrait", orientation: "squarish", count: 12 },
  // Same surface; searched separately because the first query returned almost only men.
  women: { query: "african woman smiling headshot", orientation: "squarish", count: 12 },
  // Surface 1: proof of work (what a design/tech/media student would actually upload).
  logo: { query: "logo design process sketch", orientation: "landscape", count: 12 },
  appUi: { query: "mobile app interface design", orientation: "landscape", count: 12 },
  packaging: { query: "packaging design mockup", orientation: "landscape", count: 12 },
  poster: { query: "event flyer design", orientation: "portrait", count: 12 },
  // Surface 3: a delivered piece for the "Logo and brand kit" contract.
  delivery: { query: "logo mockup", orientation: "landscape", count: 12 },
};

// A talent's proof or delivery must not be someone else's real brand: that would
// present a famous company's logo as a student's own work.
const REAL_BRANDS = /(kfc|domino|gelatissimo|coca|pepsi|nike|adidas|starbucks|mcdonald|apple|iphone|google|samsung|amazon|netflix|spotify|burger king|subway)/i;

async function search({ query, orientation, count }) {
  const url = `https://api.unsplash.com/search/photos?query=${encodeURIComponent(query)}&orientation=${orientation}&per_page=20&content_filter=high`;
  const r = await fetch(url, { headers: { Authorization: `Client-ID ${KEY}`, "Accept-Version": "v1" } });
  if (!r.ok) throw new Error(`Unsplash ${r.status} for "${query}": ${await r.text()}`);
  console.log(`"${query}": ${r.status}, rate limit left ${r.headers.get("x-ratelimit-remaining")}`);
  const { results } = await r.json();
  const kept = results.filter((p) => !REAL_BRANDS.test(`${p.alt_description} ${p.description}`)).slice(0, count);
  return kept.map((p) => ({
    id: p.id,
    color: p.color, // dominant colour, used as the loading placeholder
    alt: p.alt_description,
    thumb: p.urls.thumb,
    small: p.urls.small,
    regular: p.urls.regular,
    by: p.user.name,
    byUrl: `${p.user.links.html}?${UTM}`,
    photoUrl: `${p.links.html}?${UTM}`,
  }));
}

(async () => {
  const out = { fetchedAt: new Date().toISOString(), unsplash: `https://unsplash.com/?${UTM}` };
  for (const [name, set] of Object.entries(SETS)) out[name] = await search(set);
  const file = path.join(__dirname, "..", "data", "unsplash-examples.js");
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, `// Generated by prototypes/tools/fetch-unsplash.js — example images, not user data.\nwindow.KD_EXAMPLE_IMAGES = ${JSON.stringify(out, null, 2)};\n`);
  console.log("wrote", file, Object.fromEntries(Object.entries(SETS).map(([k]) => [k, out[k].length])));
})();
